text:
**Railway → Postgres 서비스 → Console**에서 아래 전체를 한 번에 붙여 넣으세요. `root@...#` 상태에서 실행할 수 있습니다.

기존 직원·계정 데이터는 유지합니다. 테이블이 이미 있거나 오류가 발생하면 변경을 중단하고 되돌립니다.

```bash
PGPASSWORD="$POSTGRES_PASSWORD" psql -X -v ON_ERROR_STOP=1 -h 127.0.0.1 -U "${POSTGRES_USER:-postgres}" -d "${POSTGRES_DB:-postgres}" <<'V5_SQL'
BEGIN;

SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '15s';

DO $guard$
BEGIN
  IF to_regclass('public.employees') IS NULL
     OR to_regclass('public.user_accounts') IS NULL THEN
    RAISE EXCEPTION 'Required employee/account tables are missing.';
  END IF;

  IF to_regclass('public.background_checks') IS NOT NULL
     OR to_regclass('public.background_check_views') IS NOT NULL THEN
    RAISE EXCEPTION 'V5 tables already exist. Inspect schema before proceeding.';
  END IF;
END $guard$;

SET LOCAL search_path = public;

LOCK TABLE employees, user_accounts IN SHARE MODE;

CREATE TEMP TABLE v5_before_counts ON COMMIT DROP AS
SELECT
  (SELECT COUNT(*) FROM employees) AS employees,
  (SELECT COUNT(*) FROM user_accounts) AS accounts;

SELECT 'before' AS phase, employees, accounts
FROM v5_before_counts;

CREATE TABLE background_checks (
    request_id VARCHAR(36) PRIMARY KEY,
    employee_id VARCHAR(32) NOT NULL REFERENCES employees(employee_id),
    requested_by BIGINT NOT NULL REFERENCES user_accounts(id),
    requested_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    dispatch_deadline TIMESTAMP WITH TIME ZONE NOT NULL,
    check_id VARCHAR(128) UNIQUE,
    local_state VARCHAR(16) NOT NULL CHECK (
        local_state IN ('DISPATCHING','KNOWN','UNKNOWN','REJECTED','NOT_SENT')
    ),
    status VARCHAR(16) CHECK (status IN ('pending','clear','flagged')),
    observed_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,
    last_http_code INTEGER,
    last_outcome VARCHAR(40),
    poll_deadline TIMESTAMP WITH TIME ZONE NOT NULL,
    next_poll_at TIMESTAMP WITH TIME ZONE,
    poll_count INTEGER NOT NULL DEFAULT 0,
    poll_stopped BOOLEAN NOT NULL DEFAULT FALSE,
    stop_reason VARCHAR(40),
    refreshing_until TIMESTAMP WITH TIME ZONE,
    CHECK (
        (local_state = 'KNOWN' AND check_id IS NOT NULL AND status IS NOT NULL)
        OR
        (local_state <> 'KNOWN' AND check_id IS NULL AND status IS NULL)
    )
);

CREATE INDEX background_checks_employee_time
ON background_checks(employee_id, requested_at DESC);

CREATE TABLE background_check_views (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    request_id VARCHAR(36) NOT NULL REFERENCES background_checks(request_id),
    viewed_by BIGINT NOT NULL REFERENCES user_accounts(id),
    viewed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    action VARCHAR(16) NOT NULL CHECK (action IN ('DETAIL','RESOLVE')),
    status VARCHAR(16) CHECK (status IN ('pending','clear','flagged')),
    outcome VARCHAR(40) NOT NULL
);

CREATE INDEX background_check_views_request_time
ON background_check_views(request_id, viewed_at DESC);

DO $verify$
BEGIN
  IF (SELECT employees FROM v5_before_counts) <> (SELECT COUNT(*) FROM employees)
     OR (SELECT accounts FROM v5_before_counts) <> (SELECT COUNT(*) FROM user_accounts) THEN
    RAISE EXCEPTION 'Existing row counts changed. Rolling back V5.';
  END IF;
END $verify$;

SELECT
  'after' AS phase,
  (SELECT COUNT(*) FROM employees) AS employees,
  (SELECT COUNT(*) FROM user_accounts) AS accounts,
  (SELECT COUNT(*) FROM background_checks) AS checks,
  (SELECT COUNT(*) FROM background_check_views) AS views;

COMMIT;
V5_SQL
```

**마지막에 `COMMIT`이 출력되면 생성 완료**입니다. 실행 결과를 보내주시면 이어서 확인하겠습니다.
